 Exemple : description VHDL des portes logiques de base
library ieee;
use ieee.std_logic_1164.all;
-- déclaration de l'entité
entity portes_logiques is
port( A,B: in std_logic;
S1, S2, S3, S4, S5, S6:out std_logic);
end portes_logiques;
-- description de l'architecture
architecture description of portes_logiques is
begin
S1 <= not(A);
S2 <= A and B;
S3 <= A or B;
S4 <= A xor B;
S4 <= A nand B;
S5 <= A nor B;
end description;
