library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
entity add_complet is
Port (
A ,B,Cin : in STD_LOGIC;
S,Cout : out STD_LOGIC
);
end add_complet;
architecture description of add_complet is
begin
S <= A xor B xor Cin;
Cout <= (A and B) or (Cin and (A xor B));
end description;

