Library ieee;
USE ieee.std_logic_1164.all;
Entity mux is
Port (
E0, E1, E2, E3 : in std_logic;
SEL : in std_logic_vector (1 downto 0);
S: out std_logic
);
End mux;
Architecture comportement of mux is
Begin
process(E0, E1, E2, E3, SEL)
begin
if SEL = "00" then
S <= E0;
elsif SEL = "01" then
S <= E1;
elsif SEL = "02" then
S <= E2;
elsif SEL = "11" then
S <= E3;
else
S <= 'X'; -- si sel n'est ni à 1 ni à 0, on affecte X à S
end if;
end process;
End comportement;
